def check_dict_case(dict):
    if not dict:
        return False

    lower_case = True
    upper_case = True

    for key in dict.keys():
        if not isinstance(key, str):
            return False
        if key != key.lower():
            lower_case = False
        if key != key.upper():
            upper_case = False

    return lower_case or upper_case
